solutions.naive:
class Solution:
    def longestValidParentheses(self, s: str) -> int:
        best = 0
        n = len(s)
        for i in range(n):
            bal = 0
            for j in range(i, n):
                bal += 1 if s[j] == '(' else -1
                if bal < 0:
                    break
                if bal == 0:
                    best = max(best, j - i + 1)
        return best

solutions.better:
class Solution:
    def longestValidParentheses(self, s: str) -> int:
        n = len(s)
        dp = [0] * n
        best = 0
        for i in range(1, n):
            if s[i] == ')':
                if s[i - 1] == '(':
                    dp[i] = 2 + (dp[i - 2] if i >= 2 else 0)
                else:
                    j = i - dp[i - 1] - 1
                    if j >= 0 and s[j] == '(':
                        dp[i] = dp[i - 1] + 2 + (dp[j - 1] if j >= 1 else 0)
                best = max(best, dp[i])
        return best

